import pytest
from isort.parse import file_contents
from isort.settings import Config


def test_file_contents_comprehensive_uncovered_paths():
    # 1. Test trailing newline handling (lines 148-149)
    # 2. Test old_finders config (lines 153-156)
    # 3. Test section comments and section_comments_end (lines 193-198)
    # 4. Test isort:imports- and isort: imports- placement markers (lines 200-207)
    # 5. Test float_to_top with comments / multiline skip / float logic (lines 214-255)
    # 6. Test semicolons in statements (lines 258-261)
    # 7. Test comment with from import when len(line_parts) == 2 (lines 279-280)
    # 8. Test parentheses with multiline comments and nested comments (lines 282-352)
    # 9. Test cimports and "import " not in import_string (lines 361-371)
    # 10. Test 'as' clause mapping, redundant aliases removal, and comments on straight/from imports (lines 387-435)
    # 11. Test verbose output (verbose=True, only_modified=False/True) (lines 442-447, 561-566)
    # 12. Test placed_module == "" warning (lines 449-453, 568-574)
    # 13. Test MissingSection exception (lines 456, 576)
    # 14. Test force_single_line with comments (lines 468-481)
    # 15. Test above comments extraction for 'from' and 'straight' imports (lines 486-506, 538-558)
    # 16. Test existing module root update (lines 514-516)
    # 17. Test trailing comma checking (lines 522-527)
    # 18. Test straight import section handling (lines 533-582)

    content = (
        "# isort:imports-CUSTOM\n"
        "# isort: imports-CUSTOM2\n"
        "import os, sys; import math\n"
        "from typing import Any, # inline comment\n"
        "    Union\n"
        "import numpy as numpy # comment\n"
        "from collections import ( \n"
        "    defaultdict, # comment dict\n"
        "    OrderedDict as OD\n"
        ")\n"
        "import unittest as unittest\n"
    )

    config = Config(
        float_to_top=True,
        verbose=True,
        only_modified=False,
        remove_redundant_aliases=True,
        force_single_line=False,
        combine_as_imports=True,
        sections=["CUSTOM", "CUSTOM2", "STDLIB", "THIRDPARTY", "FIRSTPARTY", "LOCALFOLDER"],
    )

    parsed = file_contents(content, config=config)
    assert parsed.original_line_count > 0
    assert "CUSTOM" in parsed.place_imports
    assert "CUSTOM2" in parsed.place_imports


def test_file_contents_old_finders_and_missing_section():
    config = Config(old_finders=True)
    content = "import unknown_module_xyz_abc\n"
    parsed = file_contents(content, config=config)
    assert parsed is not None


def test_file_contents_empty_and_trailing_newline():
    # Test empty string and string ending without newline vs with newline
    res1 = file_contents("")
    assert res1.original_line_count == 0

    res2 = file_contents("import os\n")
    assert res2.in_lines[-1] == ""

    res3 = file_contents("import os\r")
    assert res3.in_lines[-1] == ""


def test_file_contents_cimport_and_no_import_string():
    content = "from module cimport *\n"
    config = Config()
    parsed = file_contents(content, config=config)
    assert parsed is not None


def test_file_contents_float_to_top_multiline_skip():
    content = (
        "# isort: skip\n"
        "(\n"
        "x = 1\n"
        ")\n"
        "import sys\n"
    )
    config = Config(float_to_top=True)
    parsed = file_contents(content, config=config)
    assert parsed.import_index >= 0


def test_file_contents_treat_comments_as_code_and_treat_all():
    content = (
        "# regular comment above\n"
        "import os\n"
    )
    config = Config(treat_all_comments_as_code=True)
    parsed = file_contents(content, config=config)
    assert parsed is not None

    config2 = Config(treat_comments_as_code=["# regular comment above"])
    parsed2 = file_contents(content, config=config2)
    assert parsed2 is not None


def test_file_contents_verbose_only_modified():
    content = "import os\n"
    config = Config(verbose=True, only_modified=True)
    parsed = file_contents(content, config=config)
    assert parsed is not None


def test_file_contents_backslash_escaped_imports():
    content = (
        "import \\\n"
        "    os, \\\n"
        "    sys\n"
    )
    parsed = file_contents(content)
    assert parsed is not None
